    if(current?.entry?.imageUrl){const slot=target.querySelector('[data-live-current-image]'),url=await imageFor(current.entry.imageUrl,`entry-${current.entry.id}`);if(slot?.isConnected&&url)slot.outerHTML=`<img alt="${esc(current.entry.car.model)}" src="${url}">`}
