  function scoreButtons({name,value,attribute='data-live-judge-score'}){return `<input name="${name}" type="hidden" value="${value||''}"><div class="live-score live-score--judge">${Array.from({length:10},(_,index)=>`<button ${attribute}="${index+1}" data-live-judge-criterion="${name}" aria-pressed="${Number(value)===index+1}" class="${Number(value)===index+1?'is-selected':''}" type="button">${index+1}</button>`).join('')}</div>`}
  function judgeForm(entry){const saved=confirmedScores.get(entry.id)?.value||payload?.judgeHistory?.find(item=>item.entryId===entry.id)||{},draft=judgeDrafts.get(entry.id)||{},scores={...(saved.scores||{}),...(draft.scores||{})},note=draft.note??saved.note??'',identity=entry.member?.name||'auto',files=judgeFiles.get(entry.id)||[],locked=saved.submitted&&!editingJudges.has(entry.id);if(!canJudgeEdit(entry)||saved.submitted&&!editingJudges.has(entry.id)&&!files.some(item=>item.status!=='uploaded'))return judgeSummary(entry,saved);return `<form class="live-judge-form" data-live-judge="${esc(entry.id)}" ${locked?'data-photo-only':''}><input name="expectedVersion" type="hidden" value="${draft.expectedVersion??saved.version??0}"><input name="correction" type="hidden" value="${!!saved.submitted&&editingJudges.has(entry.id)}">${saved.submitted&&editingJudges.has(entry.id)?`<aside class="live-correction-warning"><strong>POZOR: MĚNÍŠ JIŽ POTVRZENÉ HODNOCENÍ.</strong>${payload?.categories?.find(row=>row.category===entry.category)?.status==='closed'?'<p>Kategorie je uzavřená. Změna upraví její výsledky.</p>':''}<label>Důvod opravy<input name="reason" required maxlength="240" value="${esc(draft.reason||'')}"></label></aside>`:''}<span class="live-eyebrow">POROTA · ${saved.submitted?'Hodnocení potvrzeno':'ROZEPSÁNO'}</span>${locked?`<p>Vlastní body: ${Object.entries(criteria).map(([key,label])=>`${label} ${scores[key]??'—'}/10`).join(' · ')}</p>`:''}<h4>${esc(entry.car?.nickname||entry.car?.model||'Hodnocení')}</h4>${Object.entries(criteria).map(([key,label])=>`<fieldset ${locked?'hidden':''}><legend>${label}</legend>${scoreButtons({name:key,value:scores[key]})}</fieldset>`).join('')}<details><summary>Poznámka a fotografie</summary><textarea ${locked?'readonly hidden':''} name="note" maxlength="1000" rows="3" placeholder="Interní poznámka poroty (volitelné)">${esc(note)}</textarea><label class="live-file"><span>Vyfotografovat auto</span><input accept="image/jpeg,image/png,image/webp" capture="environment" name="judgePhoto" type="file"><small>Vyber další fotografie; před odesláním je můžeš jednotlivě odebrat.</small></label><label class="live-gallery-picker">Vybrat z galerie<input accept="image/jpeg,image/png,image/webp" multiple name="judgeGallery" type="file"></label><div class="live-upload-previews" data-live-judge-previews>${previewsMarkup(files,'data-live-remove-judge-file')}</div>${saved.photos?.length?`<div class="live-judge-photos">${saved.photos.map(photo=>`<span data-live-judge-photo="${esc(photo.imageUrl)}" data-live-judge-photo-key="judge-${esc(photo.id)}">Načítám foto…</span>`).join('')}</div>`:''}</details><p class="live-form-error" data-live-judge-error role="status"></p><div class="live-judge-actions"><button class="member-secondary" data-live-cancel-judge type="button">Zrušit hodnocení</button><button class="member-secondary" ${locked||saved.submitted?'hidden':''} data-judge-draft type="submit">Uložit koncept</button><button class="live-primary" data-judge-submit type="submit">${locked?'Odeslat zbývající fotografie':saved.submitted?'Potvrdit změnu hodnocení':`Uložit hodnocení „${esc(identity)}“`}</button></div></form>`}
