  function voteCanEdit(item){if(item.discipline==='show_shine')return payload?.categories?.find(row=>row.category===item.category)?.status==='live';const state=payload?.states?.best_exhaust;return state?.status==='live'&&state.entry?.id===item.entryId&&!state.entry.votingClosed}
