    root()?.addEventListener('input',event=>{const form=event.target.closest('[data-live-judge]');if(form)judgeDrafts.set(form.dataset.liveJudge,judgeValues(form))});root()?.addEventListener('change',event=>{if(event.target.matches('[data-live-upload] input[type="file"]')){addFiles(galleryFiles,event.target.files,8);event.target.value='';renderGalleryPreviews();return}const form=event.target.closest('[data-live-judge]');if(form&&['judgePhoto','judgeGallery'].includes(event.target.name)){const entryId=form.dataset.liveJudge,files=judgeFiles.get(entryId)||[];addFiles(files,event.target.files,8);if(files.length)judgeFiles.set(entryId,files);event.target.value='';renderJudgePreviews(form,entryId)}});
